import pytest

from patSite import db
from patSite.auth import is_safe_redirect
from patSite.Models import Users
from tests.conftest import log_in

# Generated by the app's old code: Werkzeug 1.0.1 generate_password_hash("hunter22", "sha256")
LEGACY_HASH_HUNTER22 = "sha256$CXTckGVy$4b169b6b390c0f76d67867c27ee977212a171b1dafcb8ad1d1e3c4a2c78cfd3d"


def test_logout_when_logged_out_redirects_instead_of_crashing(client):
    resp = client.get("/logout")
    assert resp.status_code == 302
    assert resp.headers["Location"].startswith("/login")


def test_login_ignores_external_next(client, user):
    resp = log_in(client, next_page="https://evil.example/phish")
    assert resp.status_code == 302
    assert resp.headers["Location"] == "/"


def test_login_follows_local_next(client, user):
    resp = log_in(client, next_page="/contact")
    assert resp.headers["Location"] == "/contact"


@pytest.mark.parametrize("target,ok", [
    ("/contact", True),
    ("/", True),
    ("https://evil.example", False),
    ("//evil.example", False),
    ("/\\evil.example", False),
    ("javascript:alert(1)", False),
    ("", False),
    (None, False),
])
def test_is_safe_redirect(target, ok):
    assert is_safe_redirect(target) is ok


def test_wrong_password_is_rejected(client, user):
    resp = log_in(client, password="wrong")
    assert resp.headers["Location"].startswith("/login")


def test_signup_rejects_invalid_email(client, app):
    client.post("/signup", data={"name": "Pat", "email": "not-an-email",
                                 "password": "abcdefgh", "confirm": "abcdefgh"})
    assert Users.query.count() == 0


def test_signup_stores_modern_hash_not_plaintext(client, app):
    client.post("/signup", data={"name": "Pat", "email": "New@Example.com",
                                 "password": "abcdefgh", "confirm": "abcdefgh"})
    u = Users.query.one()
    assert u.email == "new@example.com"
    assert u.password != "abcdefgh"
    assert u.password.startswith("scrypt:")


def test_signup_rejects_duplicate_email_case_insensitively(client, user):
    client.post("/signup", data={"name": "Pat", "email": "PAT@example.com",
                                 "password": "abcdefgh", "confirm": "abcdefgh"})
    assert Users.query.count() == 1


def _legacy_user(app, legacy_hash):
    u = Users("old@example.com", "placeholder", "Old")
    u.password = legacy_hash
    db.session.add(u)
    db.session.commit()
    return u


def test_legacy_password_hash_logs_in_and_is_upgraded(client, app):
    u = _legacy_user(app, LEGACY_HASH_HUNTER22)
    resp = log_in(client, email="old@example.com", password="hunter22")
    assert resp.headers["Location"] == "/"
    db.session.refresh(u)
    assert u.password.startswith("scrypt:")
    assert u.check_password("hunter22")


def test_legacy_password_hash_rejects_wrong_password(client, app):
    u = _legacy_user(app, LEGACY_HASH_HUNTER22)
    resp = log_in(client, email="old@example.com", password="hunter23")
    assert resp.headers["Location"].startswith("/login")
    db.session.refresh(u)
    assert u.password == LEGACY_HASH_HUNTER22


def test_pages_have_no_leftover_junk(client):
    html = client.get("/").get_data(as_text=True)
    assert ".bg-dark<" not in html
    assert "guaranteed" not in html.lower()
    assert "1-800-GAMBLER" in html
